export type SplitDirection = "Horizontal" | "Vertical"
export type Stage = "Spec" | "Plan" | "Build" | "Review" | "Test" | "Commit" | "Done"
/**
 * What the developer (or Plan 05, for Done detection) asks of a task. Internally tagged with struct variants only
 * (A1, A17): `{"type":"Approve"}`, `{"type":"Back","stage":"Plan"}`, `{"type":"Reply","prompt":"…"}`.
 */
export type StageAction = { type: "Approve" } | { type: "Advance" } | { type: "Back"; stage: Stage } | { type: "Reply"; prompt: string } | { type: "StartFresh" } | { type: "RequestReview" } | { type: "ApproveChanges" } | { type: "RunTests" } | { type: "FixTests" } | { type: "CopyCommit" } | { type: "Commit" } | { type: "Archive" } | { type: "Restore" }
export type Task = { id: TaskId; project_id: ProjectId; workspace_id: WorkspaceId | null; title: string; stage: Stage; state: AgentState; priority: Priority; color: TaskColor | null; flagged: boolean; hidden: boolean; archived: boolean; jira_key: string | null; agent_kind: AgentKind; worktree: WorktreeChoice; worktree_path: string | null; branch: string | null; memory_dir: string; primary_session: SessionId | null; claude_session_id: string | null; 
/**
 * Fixed at first session start (§4.1).
 */
linked_roots: string[]; 
/**
 * Per repo (§9).
 */
base: RepoBase[]; created_at: string; updated_at: string; stage_entered_at: string; 
/**
 * For "elapsed in the current state" (A11).
 */
state_entered_at: string; 
/**
 * When `linked_roots` were fixed (A11).
 */
links_bound_at: string | null }
export type TaskChanged = { task: Task }
/**
 * A swatch token name from `SWATCHES`, e.g. `"violet"`; separate from the stage colours.
 */
export type TaskColor = string
/**
 * One parsed line of a task's event log. `seq` is the 1-based line number; `agent_id` is the payload's subagent id,
 * normalised (no `agent-` prefix), `None` for the main agent.
 */
export type TaskEvent = { seq: number; at: string; task_id: TaskId; agent_id: string | null; event: HookEvent }
export type TaskId = string
/**
 * What `tasks_update` may change; `None` (or a missing field) leaves a field as it is, and `clear_*` empties one.
 */
export type TaskPatch = { priority: Priority | null; color: TaskColor | null; clear_color: boolean; flagged: boolean | null; hidden: boolean | null; jira_key: string | null; clear_jira_key: boolean; 
/**
 * Only before the first session starts.
 */
worktree: WorktreeChoice | null; 
/**
 * Only before the first session starts.
 */
agent_kind: AgentKind | null }
export type TasksReloaded = { container: Container }
export type TeamArrangement = "HubGraph" | "Flow"
/**
 * Every parsed hook event except `StatusLine` (Plan 05's tailer).
 */
export type TeamEvent = { task_id: TaskId; event: TaskEvent }
export type TeamPlacement = "DockGrows" | "Swap" | "OwnPane"
/**
 * One bullet of the `## Team` section: a role and the steps it owns.
 */
export type TeamRole = { role: string; steps: number[] }
export type TestFinished = { task_id: TaskId; code: number }
/**
 * The `theme` setting. `System` follows macOS; the webview resolves it (`src/lib/theme.ts`).
 */
export type ThemePreference = "System" | "Light" | "Dark"
export type View = { id: ViewId; container: Container; name: string; order: number; layout: LayoutNode }
export type ViewId = string
export type ViewsChanged = { container: Container }
/**
 * `w-<n>`, as in LiveSpec; the Tauri window label.
 */
export type WindowId = string
/**
 * One open window. `container: None` is the start screen (with `project_ids` empty); a project window lists its
 * one project, a workspace window its projects in order.
 */
export type WindowInfo = { window_id: WindowId; title: string; container: Container | null; project_ids: ProjectId[] }
export type Workspace = { id: WorkspaceId; name: string; file_path: string | null; dirty: boolean; projects: WorkspaceProject[]; policy: LinkPolicy }
export type WorkspaceBoard = "Swimlanes" | "OneProject" | "Mixed"
export type WorkspaceChanged = { workspace: Workspace }
export type WorkspaceId = string
export type WorkspaceProject = { project_id: ProjectId; order: number; protected: boolean }
/**
 * Per task, resolved from the project default at creation.
 */
export type WorktreeChoice = "Off" | "On"
export type WorktreeConvention = "ClaudeCode" | "TeamCodeManaged"

/** tauri-specta globals **/

import {
	invoke as TAURI_INVOKE,
	Channel as TAURI_CHANNEL,
} from "@tauri-apps/api/core";
import * as TAURI_API_EVENT from "@tauri-apps/api/event";
import { type WebviewWindow as __WebviewWindow__ } from "@tauri-apps/api/webviewWindow";

type __EventObj__<T> = {
	listen: (
		cb: TAURI_API_EVENT.EventCallback<T>,
	) => ReturnType<typeof TAURI_API_EVENT.listen<T>>;
	once: (
		cb: TAURI_API_EVENT.EventCallback<T>,
	) => ReturnType<typeof TAURI_API_EVENT.once<T>>;
	emit: null extends T
		? (payload?: T) => ReturnType<typeof TAURI_API_EVENT.emit>
		: (payload: T) => ReturnType<typeof TAURI_API_EVENT.emit>;
};

export type Result<T, E> =
	| { status: "ok"; data: T }
	| { status: "error"; error: E };

function __makeEvents__<T extends Record<string, any>>(
	mappings: Record<keyof T, string>,
) {
	return new Proxy(
		{} as unknown as {
			[K in keyof T]: __EventObj__<T[K]> & {
				(handle: __WebviewWindow__): __EventObj__<T[K]>;
			};
		},
		{
			get: (_, event) => {
				const name = mappings[event as keyof T];

				return new Proxy((() => {}) as any, {
					apply: (_, __, [window]: [__WebviewWindow__]) => ({
						listen: (arg: any) => window.listen(name, arg),
						once: (arg: any) => window.once(name, arg),
						emit: (arg: any) => window.emit(name, arg),
					}),
					get: (_, command: keyof __EventObj__<any>) => {
						switch (command) {
							case "listen":
								return (arg: any) => TAURI_API_EVENT.listen(name, arg);
							case "once":
								return (arg: any) => TAURI_API_EVENT.once(name, arg);
							case "emit":
								return (arg: any) => TAURI_API_EVENT.emit(name, arg);
						}
					},
				});
			},
		},
	);
}
